export const today=()=>new Date().toLocaleDateString('en-CA');
export function nextDate(date,days){const d=new Date(date+'T12:00:00');d.setDate(d.getDate()+Number(days));return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`;}
export function escapeHTML(s){return String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));}
export const definitions={assets:{title:'設備台帳',singular:'設備',prefix:'EQ',fields:{name:['設備名稱','text'],zone:['所在區域',['A 區・常溫倉','B 區・冷藏倉','C 區・出貨區','D 區・公用設施']],category:['設備類別',['搬運設備','空調冷鏈','消防安全','電力照明','建築設施']],status:['運作狀態',['正常','待維修','停用']],owner:['負責人','text'],due:['下次保養','date']}},orders:{title:'維修工單',singular:'工單',prefix:'WO',fields:{name:['工單主旨','text'],asset:['關聯設備','asset'],priority:['優先級',['緊急','高','一般','低']],status:['工單狀態',['待處理','進行中','已完成']],owner:['指派人員','text'],due:['預計完成','date'],cost:['維修費用（NT$）','number'],note:['處理說明','textarea']}},plans:{title:'保養排程',singular:'保養計畫',prefix:'PM',fields:{name:['保養項目','text'],asset:['關聯設備','asset'],owner:['負責人','text'],due:['下次執行','date'],interval:['週期間隔（天）','number']}},inspections:{title:'巡檢紀錄',singular:'巡檢',prefix:'IN',fields:{name:['巡檢項目','text'],asset:['關聯設備','asset'],owner:['巡檢人員','text'],due:['巡檢日期','date'],status:['巡檢結果',['待巡檢','合格','異常']],note:['巡檢內容／異常說明','textarea']}},parts:{title:'備品庫存',singular:'備品',prefix:'PT',fields:{name:['備品名稱','text'],zone:['存放位置','text'],quantity:['庫存數量','number'],minimum:['安全庫存','number'],unit:['單位','text']}},audit:{title:'操作紀錄'}};
export function validate(type,row,assets=[]){const def=definitions[type];if(!def?.fields)throw Error('無效資料類型');for(const [key,[label,kind]] of Object.entries(def.fields)){const v=row[key];if(key!=='note'&&(v===undefined||String(v).trim()===''))throw Error(label+'為必填');if(Array.isArray(kind)&&!kind.includes(v))throw Error(label+'無效');if(kind==='number'&&(!Number.isFinite(Number(v))||Number(v)<0))throw Error(label+'必須為非負數');if(['quantity','minimum','interval'].includes(key)&&!Number.isInteger(Number(v)))throw Error(label+'必須為整數');if(key==='interval'&&Number(v)<1)throw Error('保養週期至少 1 天');if(kind==='date'&&(!/^\d{4}-\d{2}-\d{2}$/.test(v)||Number.isNaN(Date.parse(v+'T12:00:00'))||nextDate(v,0)!==v))throw Error(label+'無效');if(kind==='asset'&&!assets.some(a=>a.id===v))throw Error('請選擇有效設備');if(String(v??'').length>4000)throw Error(label+'過長');}return row;}
export function validateBackup(data){if(data?.version!==1)throw Error('不支援的備份版本');for(const key of ['assets','orders','plans','inspections','parts','audit'])if(!Array.isArray(data[key])||data[key].length>10000)throw Error('備份結構不正確');for(const type of ['assets','orders','plans','inspections','parts']){const ids=new Set();for(const row of data[type]){if(typeof row.id!=='string'||ids.has(row.id))throw Error('紀錄編號錯誤或重複');ids.add(row.id);validate(type,row,data.assets);}}for(const row of data.audit)if(typeof row.name!=='string'||typeof row.time!=='string')throw Error('操作紀錄格式錯誤');return data;}
